async function recolorEmojiSvg(dataUrl,from,to){const xml=new DOMParser().parseFromString(await(await fetch(dataUrl)).text(),'image/svg+xml');if(xml.querySelector('parsererror'))throw new Error('SVG non leggibile');const norm=v=>(v||'').toLowerCase().replace(/\s/g,''),colors=new Set(['black','#000','#000000','rgb(0,0,0)',norm(from)]);for(const el of [xml.documentElement,...xml.querySelectorAll('*')]){for(const attr of ['stroke','fill'])if(colors.has(norm(el.getAttribute(attr))))el.setAttribute(attr,to);if(el.hasAttribute('style')){el.setAttribute('style',el.getAttribute('style').replace(/(stroke|fill)\s*:\s*([^;]+)/gi,(all,prop,value)=>colors.has(norm(value))?prop+':'+to:all))}}return dataUrlFromBlob(new Blob([new XMLSerializer().serializeToString(xml)],{type:'image/svg+xml'}))}
