function matchesFontCategory(f,category){switch(category){case 'child':return f.weight>=72&&f.shape>=55;case 'round':return f.shape>=72;case 'square':return f.shape<=28;case 'art':return f.art>=70;case 'serif':return f.category==='serif';case 'sans':return f.category==='sans-serif';case 'hand':return f.category==='handwriting';case 'mono':return f.category==='monospace';case 'outline':return !!f.native;default:return true}}
